#!/usr/bin/env python3
"""Generate the self-contained offline campaign studio from current primary SVGs."""
import json
from paints import bird_samples
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
templates={p.stem:p.read_text() for p in (ROOT/'assets/primary').glob('*.svg') if p.stem!='pwa-maskable'}
data=json.dumps({'templates':templates,'themes':json.loads((ROOT/'source/themes.json').read_text()),'samples':bird_samples()})
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Swoovr — Brand Studio</title>
<style>*{box-sizing:border-box}body{margin:0;background:#f3f0f7;color:#23162f;font:16px system-ui,sans-serif}header{background:#23162f;color:white;padding:32px 5vw}h1{margin:0;font-size:34px}header p{color:#d1bdeb;max-width:720px}main{max-width:1500px;margin:auto;padding:32px;display:grid;grid-template-columns:320px 1fr;gap:32px}aside,article{background:white;border-radius:20px;padding:24px}label{display:block;margin:20px 0 8px;font-weight:650}input,select{width:100%;padding:12px;border:1px solid #cfc7da;border-radius:8px;font:inherit}small{display:block;color:#6e607d;margin-top:8px;line-height:1.5}button{padding:12px 18px;border:0;border-radius:9px;background:#7228e8;color:white;font:inherit;cursor:pointer;margin:12px 8px 0 0}button.secondary{background:#eee7f8;color:#5420c5}.stage{min-height:430px;display:grid;place-items:center;background:repeating-conic-gradient(#eae7ef 0% 25%,#f8f7fa 0% 50%) 50%/24px 24px;border-radius:14px;padding:24px}.stage svg{max-width:100%;max-height:500px;height:auto}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:24px}.cards button{margin:0;padding:12px;background:#f4f0fa;color:#23162f;font-size:12px}.cards img{width:100%;border-radius:16px}#error{color:#a00;min-height:24px}.hint{font-size:14px;line-height:1.6;color:#6e607d}footer{padding:24px 5vw;color:#6e607d;font-size:14px}@media(max-width:850px){main{grid-template-columns:1fr;padding:16px}.cards{grid-template-columns:repeat(3,1fr)}}
</style><header><h1>Swoovr / Brand Studio</h1><p>One bird. Your colours. Build a campaign treatment, then download a real SVG or a high-resolution PNG. Works offline, without installing anything.</p></header><main><aside><label for="preset">Palette</label><select id="preset"></select><label for="layout">Artwork</label><select id="layout"></select><label for="bird">Bird colours</label><input id="bird"><small>1–9 hex colours separated by commas</small><label for="word">Wordmark colours</label><input id="word"><label for="background">Background colours</label><input id="background"><small>Standalone marks and lockups stay transparent.</small><label for="style">Bird treatment</label><select id="style"><option value="soft">Soft flag bands</option><option value="bands">Crisp flag bands</option><option value="blend">Continuous blend</option><option value="union-jack">Pink Union Jack pattern</option></select><label for="wordStyle">Wordmark treatment</label><select id="wordStyle"><option value="blend">Continuous blend</option><option value="soft">Soft flag bands</option><option value="bands">Crisp flag bands</option><option value="union-jack">Pink Union Jack pattern</option></select><label for="backgroundStyle">Background treatment</label><select id="backgroundStyle"><option value="blend">Continuous blend</option><option value="soft">Soft flag bands</option><option value="bands">Crisp flag bands</option><option value="union-jack">Pink Union Jack pattern</option></select><button id="swapPaints" class="secondary">Swap bird and background</button><label for="balance">Flag colour balance</label><select id="balance"><option value="area">Visible bird area</option><option value="linear">Geometric stripe widths</option></select><small>Area balance keeps colours represented as you rotate. Linear preserves literal stripe widths.</small><label for="angle">Paint angle</label><input id="angle" type="range" min="0" max="360" value="0"><small id="angleValue">0° · left to right</small><small>Optional per-layer angles override the shared paint angle.</small><label for="birdAngle">Bird angle override</label><input id="birdAngle" type="number" placeholder="Shared angle"><label for="wordAngle">Wordmark angle override</label><input id="wordAngle" type="number" placeholder="Shared angle"><label for="backgroundAngle">Background angle override</label><input id="backgroundAngle" type="number" placeholder="Shared angle"><label for="size">PNG width</label><select id="size"><option>1024</option><option>2048</option><option selected>4096</option><option>8192</option></select><p id="error" role="status"></p><button id="svgDownload">Download SVG</button><button id="pngDownload" class="secondary">Download PNG</button><p class="hint">For ICO, ICNS and complete export sets, use build.sh or scripts/build.py. Palette edits here do not change themes.json.</p></aside><article><div class="stage" id="stage"></div><p class="hint">These are clean vector reconstructions of the supplied concept. The wordmark is outlined custom lettering, not an identified alphabet font. Flag presets adapt colour shares to the bird. Choose crisp bands and geometric widths for literal stripes. The pink Union Jack is custom campaign artwork.</p><div class="cards" id="cards"></div></article></main><footer>Open README.md for installation, source files and platform notes. Logos are transparent; background settings apply to tiles and marketing canvases.</footer><script>
const DATA=__DATA__, $=id=>document.getElementById(id);let current='',activeWeights={},activeColours={};
function cols(id){const a=$(id).value.split(',').map(x=>x.trim());if(a.length<1||a.length>9||a.some(x=>!/^#[a-f0-9]{6}$/i.test(x)))throw Error('Use 1–9 colours in #RRGGBB format.');return a}
__PAINTS__
function layerOptions(t,key,angle){return {style:t[key+'_style']??(key==='bird'?(t.style||'blend'):'blend'),weights:t[key+'_weights']??(key==='bird'?t.weights:null),balance:t[key+'_balance']??(key==='bird'?(t.balance||'area'):'linear'),angle:t[key+'_angle']??angle}}
function artwork(layout,t,angle){let s=DATA.templates[layout];const paints={};for(const key of ['bird','word','background']){const o=layerOptions(t,key,angle);paints[key]=flagPaint('studio-'+key,t[key],o.angle,o.style,o.weights,o.balance)}s=s.replaceAll('#7228E8','__BIRD__').replaceAll('#23162F','__WORD__').replaceAll('#FFFFFF','__BG__').replaceAll('__BIRD__',paints.bird.paint).replaceAll('__WORD__',paints.word.paint).replaceAll('__BG__',paints.background.paint);return s.replace('<defs>','<defs>'+paints.bird.def+paints.word.def+paints.background.def)}
const styleId=key=>key==='bird'?'style':key+'Style';
function readTheme(){const t={bird:cols('bird'),word:cols('word'),background:cols('background'),bird_balance:$('balance').value,background_balance:'linear',word_balance:'linear'};for(const key of ['bird','word','background']){t[key+'_style']=$(styleId(key)).value;t[key+'_weights']=JSON.stringify(t[key])===JSON.stringify(activeColours[key])?activeWeights[key]:null;const value=$(key+'Angle').value;if(value!=='')t[key+'_angle']=Number(value)}return t}
function update(){try{const angle=Number($('angle').value);current=artwork($('layout').value,readTheme(),angle);$('stage').innerHTML=current;$('error').textContent='';$('angleValue').textContent=angle+'°';}catch(e){current='';$('error').textContent=e.message}}
function assignTheme(t){for(const key of ['bird','word','background']){const o=layerOptions(t,key,t.angle||0);$(key).value=t[key].join(',');$(styleId(key)).value=o.style;$(key+'Angle').value=t[key+'_angle']??'';activeColours[key]=t[key];activeWeights[key]=o.weights}$('balance').value=t.bird_balance||t.balance||'area';update()}
function preset(){const t=DATA.themes[$('preset').value];$('angle').value=t.angle||0;assignTheme(t)}
$('swapPaints').onclick=()=>{try{const t=readTheme();[t.bird,t.background]=[t.background,t.bird];for(const field of ['style','weights','balance','angle']){[t['bird_'+field],t['background_'+field]]=[t['background_'+field],t['bird_'+field]]}t.background_balance='linear';assignTheme(t)}catch(e){$('error').textContent=e.message}};

function download(blob,ext){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='swoovr-'+$('layout').value+'-'+$('preset').value+'.'+ext;a.click();setTimeout(()=>URL.revokeObjectURL(u),5000)}
$('svgDownload').onclick=()=>{if(current)download(new Blob([current],{type:'image/svg+xml'}),'svg')};
$('pngDownload').onclick=()=>{if(!current)return;const image=new Image(),u=URL.createObjectURL(new Blob([current],{type:'image/svg+xml'}));image.onload=()=>{const c=document.createElement('canvas');c.width=Number($('size').value);c.height=Math.round(c.width*image.height/image.width);const ctx=c.getContext('2d');ctx.drawImage(image,0,0,c.width,c.height);c.toBlob(blob=>{if(blob)download(blob,'png');else $('error').textContent='PNG export failed; use a smaller width.'});URL.revokeObjectURL(u)};image.onerror=()=>{$('error').textContent='SVG could not be rendered.';URL.revokeObjectURL(u)};image.src=u};
for(const name of Object.keys(DATA.themes))$('preset').add(new Option(DATA.themes[name].label||name,name));
for(const name of Object.keys(DATA.templates))$('layout').add(new Option(name,name));
$('layout').value='horizontal';$('preset').onchange=preset;for(const id of ['layout','bird','word','background','angle','style','balance','wordStyle','backgroundStyle','birdAngle','wordAngle','backgroundAngle'])$(id).addEventListener('input',update);
for(const [name,t] of Object.entries(DATA.themes)){const b=document.createElement('button'),im=document.createElement('img');im.alt=name+' icon';im.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(artwork('app-rounded',t,t.angle||0));b.append(im,document.createTextNode(name));b.onclick=()=>{$('preset').value=name;preset()};$('cards').append(b)}preset();
</script></html>'''
(ROOT/'PREVIEW.html').write_text(html.replace('__DATA__',data).replace('__PAINTS__',(ROOT/'scripts/paints.js').read_text()))
print('PREVIEW.html generated')
